"""Verify complete PR46 scope, exact retained manifests and hosted source bindings."""
import pathlib,json,hashlib,subprocess,re
r=pathlib.Path('review46');root=pathlib.Path('little-say-qa');load=lambda p:json.loads(pathlib.Path(p).read_bytes());sha=lambda b:hashlib.sha256(b).hexdigest()
def raw(*a):return subprocess.check_output(['git',*a],cwd=root)
def git(*a):return raw(*a).decode().strip()
d=load(r/'initial.json');head=d['pr']['head']['sha'];base=d['master']['sha'];commits=git('rev-list','--reverse',base+'..'+head).splitlines();assert commits==[c['sha'] for c in d['commits']];paths=git('diff','--name-only',base,head).splitlines();assert paths==sorted(f['filename'] for f in d['files']);assert len(paths)==d['pr']['changed_files']==8 and len(commits)==d['pr']['commits']==2
assert raw('diff','--binary','18aa7c08615ecf60c8583f0590dcce8ed389f0ea','373fc57b9bee58160cbe924019f41161d4c02e48')==raw('diff','--binary',base,head)
for p in ['.github/workflows/ci.yml','package-lock.json','firebase.json','vitest.integration.config.ts','apps/server/test/accounts.integration.test.ts','apps/server/test/firebase.integration.test.ts','apps/server/test/database.integration.test.ts','scripts/release/common.ts']:assert raw('show',head+':'+p)==raw('show',base+':'+p),p
def inv(c):return {'sha':c,'parents':git('show','-s','--format=%P',c).split(),'subject':git('show','-s','--format=%s',c),'perParentPaths':{p:git('diff','--name-status',p,c).splitlines() for p in git('show','-s','--format=%P',c).split()}}
scope={'head':head,'actualTarget':base,'apiBase':d['pr']['base']['sha'],'mergeBase':git('merge-base',base,head),'headParents':git('show','-s','--format=%P',head).split(),'targetParents':git('show','-s','--format=%P',base).split(),'commits':[inv(c) for c in commits],'incomingTargetCommits':[inv(c) for c in git('rev-list','--reverse','18aa7c08615ecf60c8583f0590dcce8ed389f0ea..'+base).splitlines()],'files':[{'path':p,'sha256':sha(raw('show',head+':'+p)),'purpose':'Maintained boundary regression' if '.test.' in p else 'Maintained source-validation usage documentation' if p.startswith('docs/') else 'Shared real command wiring or manually gated validation job'} for p in paths],'totals':{'commits':len(commits),'files':len(paths),'additions':sum(f['additions'] for f in d['files']),'deletions':sum(f['deletions'] for f in d['files'])},'priorDiffByteIdentical':True,'automaticCiAndAllIntegrationTestsUnchanged':True}
for a,b in zip(scope['commits'],d['commits']):assert a['parents']==[p['sha'] for p in b['parents']]
(r/'scope.json').write_bytes((json.dumps(scope,indent=2)+'\n').encode())
old=r/'owner/42cfe8fa1b9fd748476253d60d126a913e2c6b5a';new=r/'owner/67ca22a9dbb9b7f31bd73e5145b394529455c8cf';m=load(old/'manifest.json');n=load(new/'impact-master7688118/artifact-hashes.json')
assert sha((old/'manifest.json').read_bytes())=='0cfe54d5007b936edaac93eabec108d428df812e87d7508ba82d2a5027a98bb6'
assert sha((new/'impact-master7688118/artifact-hashes.json').read_bytes())=='16ba5c3a478f5e8300af3c473cd950b94ed77c08c2d12a59f480b3d16d782756'
for f in m['evidenceFiles']:assert sha((old/f['path']).read_bytes())==f['sha256'],f['path']
for f in m['changedFiles']:assert sha(raw('show',head+':'+f['path']))==f['sha256'],f['path']
