assert {j['name']:j['conclusion'] for j in jobs}=={'validate':'success','prepare':'skipped','server':'skipped','native':'skipped','submit':'skipped','ota':'skipped','finalize':'skipped'}
log=(r/'manual-live.log').read_text(encoding='utf-8');clog=(r/'ci-live.log').read_text(encoding='utf-8');assert (new/'impact-master7688118/manual-validation.log').read_bytes()==(r/'manual-live.log').read_bytes();assert (new/'impact-master7688118/ci.log').read_bytes()==(r/'ci-live.log').read_bytes()
for term in [head,'persist-credentials: false','Contents: read','RELEASE_MODE: auto','RELEASE_PROFILE: internal','RELEASE_BUMP: patch','RELEASE_DRY_RUN: false','325 passed','25 passed','npm run release:validate','firebase emulators:exec --only auth --project demo-little-say','Stopping Authentication Emulator']:assert term in log,term
