out={'scope':'scope.json','ownerExactGitBlobCount':len(load(r/'identities.json')),'oldManifestSha256':sha((old/'manifest.json').read_bytes()),'currentManifestSha256':sha((new/'impact-master7688118/artifact-hashes.json').read_bytes()),'allManifestArtifactsVerified':True,'oldManifestEntries':len(m['evidenceFiles']),'currentManifestEntries':len(n['artifacts']),'all8CurrentSourceFilesMatchPriorManifest':True,'manualRun':{'id':manual['id'],'head':head,'branch':manual['head_branch'],'event':manual['event'],'workflowPath':manual['path'],'jobs':{j['name']:j['conclusion'] for j in jobs},'inputs':{'validation_only':True,'build_mode':'auto','profile':'internal','bump':'patch','dry_run':False},'inputEvidence':'REST does not expose raw dispatch inputs. Four ordinary inputs independently resolved from actual job environment, matching workflow expressions. validation_only=true inferred from the evaluated exclusive validate job condition plus six skipped jobs, not from the older dispatch record.','effectivePermissions':'Actual job log Contents:read and Metadata:read; checkout uses built-in read token transiently with persist-credentials:false. No claim all platform tokens absent; no release/provider secrets exposed to validation env.','logSha256':sha((r/'manual-live.log').read_bytes())},'ciMerge':{'sha':ci['sha'],'parents':[p['sha'] for p in ci['parents']],'tree':ci['tree']['sha'],'equalsHeadTree':True},'focusedIndependentTests':'14passed, actual shared validation subprocess/failed-exit boundaries plus candidate wiring; mockednpm and mockedcandidateoperations only, no real release operations','heavyValidationReuse':'Exact current-head hosted source validation and CI read independently; no duplicate expensive suite or additional dispatch. Original real local PostgreSQL17/Auth failure/success/cleanup retained at original373fc57, not rebound to currentcombinedbuild.'}
